print(result)

import random

def solve_social_golfers_backtracking():
    num_golfers = 36
    num_groups = 9
    num_weeks = 6
    players_per_group = 4

    # schedule[week][golfer] = group
    schedule = [[-1 for _ in range(num_golfers)] for _ in range(num_weeks)]

    # pairs_met[p1][p2] = set of weeks they met
    pairs_met = [[set() for _ in range(num_golfers)] for _ in range(num_golfers)]

    def backtrack(week, golfer):
        if week == num_weeks:
            return True

        if golfer == num_golfers:
            return backtrack(week + 1, 0)

        if schedule[week][golfer] != -1:
            return backtrack(week, golfer + 1)

        # Try assigning golfer to a group
        # To speed up, we can try groups that have space
        groups_with_space = []
        for g in range(num_groups):
            # Count how many players are already in this group
            count = 0
            for p in range(golfer):
                if schedule[week][p] == g:
                    count += 1
            if count < players_per_group:
                groups_with_space.append(g)

        # Shuffle to get a random solution
        random.shuffle(groups_with_space)

        for g in groups_with_space:
            # Check if this assignment is valid
            # Can this golfer be in group g?
            # Only if they haven't met any other player in this group in a previous week

            # Find other players already in this group
            other_players = []
            for p in range(num_golfers):
                if schedule[week][p] == g:
                    other_players.append(p)

            # Check if any of these players have already met the current golfer
            can_assign = True
            for p in other_players:
                if week in pairs_met[golfer][p]:
                    can_assign = False
                    break

            if can_assign:
                # Assign
                schedule[week][golfer] = g
                for p in other_players:
                    pairs_met[golfer][p].add(week)
                    pairs_met[p][golfer].add(week)

                if backtrack(week, golfer + 1):
                    return True

                # Backtrack
                schedule[week][golfer] = -1
                for p in other_players:
                    pairs_met[golfer][p].remove(week)
                    pairs_met[p][golfer].remove(week)

        return False

    if backtrack(0, 0):
        result = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                result.append(schedule[w][p])
        return result
    else:
        return None

