def verify_solution(solution, num_golfers=36, num_groups=9, num_weeks=6, players_per_group=4):
    if len(solution) != num_golfers * num_weeks:
        return False, "Incorrect length"

    # Check each week
    for w in range(num_weeks):
        groups = [[] for _ in range(num_groups)]
        for p in range(num_golfers):
            g = solution[w * num_golfers + p]
            if g < 0 or g >= num_groups:
                return False, f"Invalid group {g} for player {p} in week {w}"
            groups[g].append(p)

        for g in range(num_groups):
            if len(groups[g]) != players_per_group:
                return False, f"Group {g} in week {w} has {len(groups[g])} players, expected {players_per_group}"

    # Check pairs
    pairs_met = set()
    for w in range(num_weeks):
        for g in range(num_groups):
            group_players = [p for p in range(num_golfers) if solution[w * num_golfers + p] == g]
            for i in range(len(group_players)):
                for j in range(i + 1, len(group_players)):
                    p1, p2 = group_players[i], group_players[j]
                    pair = tuple(sorted((p1, p2)))
                    if pair in pairs_met:
                        return False, f"Pair {pair} met more than once"
                    pairs_met.add(pair)

    return True, "Valid"

